  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel Taller {\n  id              Int            @id @default(autoincrement())\n  nombre          String\n  usuarios        Usuario[]\n  productos       Producto[]\n  ingresosDestino IngresoStock[] @relation(\"TallerDestino\")\n\n  ingresosOrigen   IngresoStock[] @relation(\"TallerOrigen\")\n  pedidosRecibidos Pedido[]       @relation(\"PedidosRecibidos\")\n  pedidosEnviados  Pedido[]       @relation(\"PedidosEnviados\")\n}\n\nmodel Usuario {\n  id       Int     @id @default(autoincrement())\n  nombre   String\n  email    String  @unique\n  password String\n  rol      String\n  estado   String  @default(\"Activo\")\n  tallerId Int?\n  taller   Taller? @relation(fields: [tallerId], references: [id])\n  citas    Cita[]\n\n  ingresos IngresoStock[]\n\n  // 🚀 RELACIÓN PARA PEDIDOS (Agregado)\n  pedidos Pedido[]\n\n  createdAt DateTime @default(now())\n\n  @@index([tallerId])\n}\n\nmodel Producto {\n  id Int @id @default(autoincrement())\n\n  costoMaestroId Int\n  costoMaestro   CostoMaestro @relation(fields: [costoMaestroId], references: [id])\n\n  tallerId Int\n  taller   Taller @relation(fields: [tallerId], references: [id])\n\n  stockActual Int @default(0)\n  stockMin    Int @default(5)\n\n  codigo String? @default(\"\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([costoMaestroId, tallerId])\n}\n\nmodel CostoMaestro {\n  id        Int    @id @default(autoincrement())\n  categoria String\n  nombre    String\n  marca     String\n  medida    String\n\n  precioCompra Float @default(0)\n  tiempoHH     Float @default(0)\n  costoHH      Float @default(0)\n  cantTecnicos Int   @default(1)\n  precioVenta  Float @default(0)\n\n  productos Producto[]\n  ingresos  IngresoStock[]\n\n  // 🚀 RELACIÓN PARA PEDIDOS (Agregado)\n  pedidos Pedido[]\n\n  @@unique([nombre, marca, medida])\n}\n\nmodel Vehiculo {\n  placa      String @id\n  marca      String\n  modelo     String\n  clienteNom String\n  telefono   String\n  citas      Cita[]\n}\n\nmodel Servicio {\n  id       Int    @id @default(autoincrement())\n  nombre   String\n  precio   Float\n  duracion String\n  citas    Cita[]\n}\n\nmodel Cita {\n  id                 String   @id @default(cuid())\n  fecha              DateTime\n  hora_inicio        String\n  hora_fin           String\n  estado             String   @default(\"PENDIENTE\")\n  token_confirmacion String   @unique @default(cuid())\n\n  vehiculoPlaca String\n  vehiculo      Vehiculo @relation(fields: [vehiculoPlaca], references: [placa])\n\n  tecnicoId Int\n  tecnico   Usuario @relation(fields: [tecnicoId], references: [id])\n\n  servicioId Int\n  servicio   Servicio @relation(fields: [servicioId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@index([vehiculoPlaca])\n  @@index([tecnicoId])\n  @@index([servicioId])\n}\n\nmodel Proveedor {\n  id          Int            @id @default(autoincrement())\n  ruc         String         @unique\n  razonSocial String\n  telefono    String?\n  email       String?\n  direccion   String?\n  estado      String         @default(\"Activo\")\n  ingresos    IngresoStock[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Rentabilidad {\n  id           Int      @id @default(1)\n  alquiler     Float    @default(0)\n  gestion      Float    @default(0)\n  marketing    Float    @default(0)\n  herramientas Float    @default(0)\n  transporte   Float    @default(0)\n  utilidad     Float    @default(0)\n  updatedAt    DateTime @updatedAt\n}\n\nmodel IngresoStock {\n  id       Int    @id @default(autoincrement())\n  tipo     String // \"CON_RUC\", \"SIN_RUC\", \"INTERNO\"\n  motivo   String // \"CARGA_INICIAL\", \"AJUSTE\", \"TRANSFERENCIA\"\n  cantidad Int\n  estado   String @default(\"PENDIENTE\") // PENDIENTE, APROBADO, SOLICITADO\n\n  // Apuntamos al Maestro para poder solicitar cosas que aún no tenemos en stock local\n  costoMaestroId Int\n  costoMaestro   CostoMaestro @relation(fields: [costoMaestroId], references: [id])\n\n  tallerId Int // Sede que recibe\n  taller   Taller @relation(\"TallerDestino\", fields: [tallerId], references: [id])\n\n  tallerOrigenId Int? // Sede que envía (para transferencias)\n  tallerOrigen   Taller? @relation(\"TallerOrigen\", fields: [tallerOrigenId], references: [id])\n\n  proveedorId Int?\n  proveedor   Proveedor? @relation(fields: [proveedorId], references: [id])\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([costoMaestroId])\n  @@index([tallerId])\n}\n\nenum PedidoEstado {\n  PENDIENTE\n  DESPACHADO\n  RECHAZADO\n  ENTREGADO\n  CANCELADO\n}\n\nenum PedidoTipo {\n  TRANSFERENCIA\n  CLIENTE\n  SERVICIO\n}\n\n// --- MODELO DE PEDIDOS ---\nmodel Pedido {\n  id            Int          @id @default(autoincrement())\n  codigo        String       @unique\n  tipo          PedidoTipo   @default(TRANSFERENCIA)\n  estado        PedidoEstado @default(PENDIENTE)\n  cantidad      Int\n  placa         String?\n  solicitante   String?\n  observaciones String?\n\n  costoMaestroId Int\n  costoMaestro   CostoMaestro @relation(fields: [costoMaestroId], references: [id])\n\n  tallerId Int\n  taller   Taller @relation(\"PedidosRecibidos\", fields: [tallerId], references: [id])\n\n  tallerOrigenId Int?\n  tallerOrigen   Taller? @relation(\"PedidosEnviados\", fields: [tallerOrigenId], references: [id])\n\n  usuarioId Int\n  usuario   Usuario @relation(fields: [usuarioId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
